<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Save, Moon, Sun, Globe2, Database, CheckCircle2, Activity, Download, Upload, RotateCcw, FileText } from 'lucide-vue-next'
import PageHeader from '../components/PageHeader.vue'; import AppDialog from '../components/AppDialog.vue'
import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; import type { Backup, SystemStatus } from '../types/api'
const store = useResourcesStore(); const app = useAppStore(); const saving = ref(false); const saved = ref(false); const importResult = ref(''); const restorePreview = ref<Backup | null>(null); const status = ref<SystemStatus | null>(null); const logs = ref<Array<Record<string, unknown>>>([]); const timezone = ref(Intl.DateTimeFormat().resolvedOptions().timeZone); const theme = ref<'system'|'light'|'dark'>('system'); const retention = ref(30); const reminderEnabled = ref(true); const leadSeconds = ref(60); const quietStart = ref(23); const quietEnd = ref(8); const current = computed(() => store.settings.settings)
onMounted(async () => { try { await store.loadSettings(); const s = current.value; timezone.value=s.timezone; theme.value=s.theme; retention.value=s.message_retention_days; reminderEnabled.value=s.reminder_default_enabled; leadSeconds.value=s.reminder_min_lead_seconds; quietStart.value=s.reminder_quiet_start_hour; quietEnd.value=s.reminder_quiet_end_hour } catch {} try { status.value = await api.status(); logs.value = (await api.logs('limit=8')).items } catch {} })
async function save() { saving.value = true; try { const result = await api.updateSettings({ timezone:timezone.value, theme:theme.value, message_retention_days:retention.value, reminder_default_enabled:reminderEnabled.value, reminder_min_lead_seconds:leadSeconds.value, reminder_quiet_start_hour:quietStart.value, reminder_quiet_end_hour:quietEnd.value }); store.settings = result; app.setTheme(theme.value === 'dark' ? 'dark' : 'light'); saved.value = true; app.toast(result.restart_required.length ? '设置已保存，时区变更需要重启' : '设置已保存'); setTimeout(() => saved.value = false, 2500) } catch (e) { app.toast(e instanceof Error ? e.message : '保存失败') } finally { saving.value = false } }
function downloadJson(filename: string, payload: unknown) { const blob = new Blob([JSON.stringify(payload, null, 2)], { type:'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href=url; link.download=filename; link.click(); URL.revokeObjectURL(url) }
async function backup() { try { downloadJson('campuscue-backup.json', await api.backup()); app.toast('备份已下载') } catch (e) { app.toast(e instanceof Error ? e.message : '备份失败') } }
async function exportTasks() { try { downloadJson('campuscue-tasks.json', await api.exportTasks()); app.toast('任务已导出') } catch (e) { app.toast(e instanceof Error ? e.message : '导出失败') } }
async function readJson(event: Event, kind: 'import'|'restore') { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; try { const payload = JSON.parse(await file.text()); if (kind === 'restore') restorePreview.value = payload as Backup; else { const result = await api.importTasks(payload); importResult.value = `创建 ${result.created}，跳过 ${result.skipped}，重复 ${result.duplicates}`; app.toast('导入完成') } } catch (e) { app.toast(e instanceof Error ? e.message : '文件读取失败') } (event.target as HTMLInputElement).value = '' }
async function restore() { if (!restorePreview.value) return; try { await api.restore(restorePreview.value, true); restorePreview.value = null; app.toast('备份已恢复，请刷新数据') } catch (e) { app.toast(e instanceof Error ? e.message : '恢复失败') } }
</script>
<template><section class="page-content settings-page"><PageHeader eyebrow="工作台偏好" title="设置" description="调整时间、提醒、隐私和本地数据操作。"><button class="button button-primary" :disabled="saving" @click="save"><Save :size="16" />{{ saving ? '保存中…' : '保存设置' }}</button></PageHeader><div class="settings-layout"><section class="panel settings-card"><div class="settings-section"><div class="settings-section-title"><Globe2 :size="18" /><div><h3>地区与时间</h3><p>截止日期会按这个时区显示；变更后需要重启服务。</p></div></div><label>时区<select v-model="timezone"><option>{{ timezone }}</option><option>Asia/Shanghai</option><option>Asia/Tokyo</option><option>UTC</option></select></label></div><div class="settings-section"><div class="settings-section-title"><component :is="theme === 'dark' ? Moon : Sun" :size="18" /><div><h3>外观</h3><p>主题偏好会保存到你的工作台。</p></div></div><div class="theme-picker"><button v-for="item in [{value:'system',label:'跟随系统'},{value:'light',label:'浅色'},{value:'dark',label:'深色'}]" :key="item.value" :class="{ active: theme === item.value }" @click="theme = item.value as 'system'|'light'|'dark'"><Sun v-if="item.value !== 'dark'" :size="17" /><Moon v-else :size="17" />{{ item.label }}</button></div></div><div class="settings-section"><div class="settings-section-title"><Activity :size="18" /><div><h3>提醒</h3><p>设置默认提醒时间和免打扰时段。</p></div></div><label class="check-line"><input v-model="reminderEnabled" type="checkbox" />默认开启提醒</label><label>最小提前秒数<input v-model.number="leadSeconds" type="number" min="1" /></label><div class="form-grid"><label>免打扰开始小时<input v-model.number="quietStart" type="number" min="0" max="23" /></label><label>免打扰结束小时<input v-model.number="quietEnd" type="number" min="0" max="23" /></label></div></div><div class="settings-section"><div class="settings-section-title"><Database :size="18" /><div><h3>隐私与数据</h3><p>你可以控制消息原文的保留时间和数据导出。</p></div></div><label>消息保留天数<input v-model.number="retention" type="number" min="1" max="3650" /></label><div class="privacy-note"><CheckCircle2 :size="16" />本地优先 · 原文是否保留由消息策略决定</div><div class="data-actions"><button class="button button-secondary" @click="backup"><Download :size="15" />下载备份</button><button class="button button-secondary" @click="exportTasks"><Download :size="15" />导出任务</button><label class="button button-secondary upload-button"><Upload :size="15" />导入任务<input type="file" accept="application/json" @change="readJson($event,'import')" /></label><label class="button button-secondary upload-button"><RotateCcw :size="15" />恢复备份<input type="file" accept="application/json" @change="readJson($event,'restore')" /></label></div><p v-if="importResult" class="form-success">{{ importResult }}</p></div></section><aside class="panel settings-side"><p class="section-kicker">诊断</p><h3>{{ app.online ? '运行正常' : '等待连接' }}</h3><p class="muted-copy">{{ app.online ? '本地服务与通知通道已准备好。' : '请确认本地 CampusCue 服务已启动。' }}</p><div v-if="status" class="system-details"><span>运行状态<strong>{{ status.runtime }}</strong></span><span>模型<strong>{{ status.provider_configured ? '已配置' : '未配置' }}</strong></span><span>适配器<strong>{{ status.adapter_connected ? '已连接' : '未连接' }}</strong></span></div><details class="logs-preview"><summary><FileText :size="15" />最近日志（{{ logs.length }}）</summary><div><p v-for="(log,index) in logs" :key="index">{{ log.message || '系统事件' }}</p></div></details><span v-if="saved" class="form-success">已保存</span></aside></div><AppDialog :open="Boolean(restorePreview)" title="预览并恢复备份" description="确认后会替换当前本地数据。" @close="restorePreview = null"><div v-if="restorePreview" class="restore-preview"><strong>{{ restorePreview.version }} · 数据版本 {{ restorePreview.schema_version }}</strong><span>备份时间：{{ restorePreview.created_at }}</span><span>任务：{{ Array.isArray(restorePreview.data.tasks) ? restorePreview.data.tasks.length : 0 }} 条</span></div><template #footer><button class="button button-secondary" @click="restorePreview = null">取消</button><button class="button button-danger" @click="restore">确认替换并恢复</button></template></AppDialog></section></template>
